import { DockLayout, Button, Textarea, row, col, tabs, type DockApi } from "march/ui"
import { inbox, mail, edit } from "march/icons"

// gerçek hayattan: bir e-posta istemcisi. Solda gelen kutusu, sağda okuma bölmesi ve taslak; bir postaya basınca okuma
// bölmesi öne gelir, taslakta yazı varken sekmede "değişti" noktası görünür. Yerleşim bu oturumda hatırlanır.
const MAILS = [
  { from: "Ada", subject: "Toplantı saat 3'te", body: "Gündem ekte." },
  { from: "Deniz", subject: "Fatura hazır", body: "Ekim faturası sistemde." },
  { from: "Ece", subject: "Tasarım geri bildirimi", body: "Renkler çok güzel olmuş!" },
]
const mem = new Map<string, unknown>()

export function MailClient() {
  let $open = 0
  let $draft = ""
  let dock: DockApi | undefined
  const read = (i: number) => { $open = i; dock?.open("read") }
  const panels = [
    { id: "inbox", title: "Gelen kutusu", icon: inbox, min: [160, 120] as [number, number], badge: MAILS.length, content: () => <div sx={{ p: 2, flex: "col", gap: 1 }}>
      {MAILS.map((m, i) => <Button size="sm" variant="ghost" on:click={() => read(i)}>{m.from}: {m.subject}</Button>)}
    </div> },
    { id: "read", title: () => MAILS[$open]!.subject, icon: mail, content: () => <div sx={{ p: 3, flex: "col", gap: 1 }}>
      <span sx={{ text: "bold" }}>{() => MAILS[$open]!.from}</span>
      <span>{() => MAILS[$open]!.body}</span>
    </div> },
    { id: "draft", title: "Yeni posta", icon: edit, dirty: () => $draft.length > 0, content: () => <div sx={{ p: 2 }}><Textarea label="İleti" bind:value={$draft} rows={3} /></div> },
  ]
  return <div style={{ height: "20rem" }}>
    <DockLayout panels={panels} label="Posta" commands={false} api={(a) => dock = a}
      presets={{ mail: { title: "Posta", tree: () => row([0.35, tabs("inbox")], [0.65, col([0.6, tabs("read")], [0.4, tabs("draft")])]) } }}
      persist="mail-layout" storage={{ get: (k) => mem.get(k), set: (k, v) => { mem.set(k, v) } }} />
  </div>
}

import { DockLayout, Toolbar, Button, row, col, tabs, type DockApi } from "march/ui"
import { folder, fileText, terminal, bug, lock } from "march/icons"

// DockLayout'un bütün özellikleri: paneller (en küçük boyut, kapatılabilir, rozet, değişti noktası, kapalı, onShow),
// hazır düzenler + başlangıç düzeni, düzen ağacı, saklama (bellekte), ad, komut öneki, api, onChange, onClose, grup
// düğmeleri, dar kip ve sekme yeri, hareket, kendi ikonlar ve metinler, id, sınıf. Üstteki düğmeler api'yi kullanır.
export function DockLayoutLab() {
  let $changes = 0
  let $shown = 0
  let $closed = "yok"
  let $log = ["hazır"]
  let $dirty = true
  const mem = new Map<string, unknown>()
  let dock: DockApi | undefined
  const panels = [
    { id: "files", title: "Dosyalar", icon: folder, min: [120, 80] as [number, number], content: () => <p sx={{ p: 2 }}>src/ · lab.ts</p> },
    { id: "editor", title: "lab.ts", icon: fileText, dirty: () => $dirty, content: () => <div sx={{ p: 2 }}><Button size="sm" on:click={() => $dirty = !$dirty}>{$dirty ? "Kaydet" : "Değiştir"}</Button></div> },
    { id: "log", title: "Günlük", icon: terminal, closable: true, badge: () => $log.length, onShow: () => $shown++, content: () => <div sx={{ p: 2 }}>{() => $log.join(" · ")}</div> },
    { id: "debug", title: "Hata ayıklama", icon: bug, content: () => <p sx={{ p: 2 }}>kesme noktası yok</p> },
    { id: "secret", title: "Kilitli", icon: lock, disabled: true, content: () => <p>görünmez</p> },
  ]
  return <div sx={{ flex: "col", gap: 2 }}>
    <Toolbar label="Lab düğmeleri">
      <Button size="sm" variant="secondary" on:click={() => dock?.preset("wide")}>Geniş düzen</Button>
      <Button size="sm" variant="secondary" on:click={() => dock?.collapse("files")}>Dosyaları daralt</Button>
      <Button size="sm" variant="secondary" on:click={() => dock?.close("log")}>Günlüğü kapat</Button>
      <span sx={{ text: "sm" }}>değişiklik: {$changes} · görünme: {$shown} · kapatılan: {$closed}</span>
    </Toolbar>
    <div style={{ height: "20rem" }}>
      <DockLayout
        panels={panels}
        presets={{
          main: { title: "Ana", tree: () => row([0.25, tabs("files")], [0.75, col([0.6, tabs(["editor", "secret"])], [0.4, tabs(["log", "debug"])])]) },
          wide: { title: "Geniş", tree: () => row([0.5, tabs(["editor", "files"])], [0.5, tabs(["log", "debug", "secret"])]) },
        }}
        preset="main"
        layout={tabs(["editor", "files", "log", "debug", "secret"])}
        persist="lab-dock"
        storage={{ get: (k) => mem.get(k), set: (k, v) => { mem.set(k, v) } }}
        label="Lab çalışma alanı"
        commands="labDock"
        api={(a) => dock = a}
        onChange={() => $changes++}
        onClose={(id) => { $closed = id; $log = [...$log, `${id} kapandı`]; return false }}
        actions={["menu", "maximize", "collapse"]}
        narrow={300}
        narrowTabs="bottom"
        motion={false}
        icons={{ menu: "⋯", maximize: "▢", restore: "❐", collapse: "–" }}
        labels={{ menu: "Seçenekler", maximize: "Tam boy", restore: "Eski boyut", collapse: "Şeride indir", panels: "Paneller", strip: "Daralan paneller" }}
        id="lab-dock"
        class="lab-dock"
      />
    </div>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { DockLayoutLab } from "./DockLayoutLab.tsx"

// DockLayoutLab'in testleri: sekmeler, kendi metinler, onClose, api ve kapalı panel
test("beş panelin sekmesi var; ad, id ve sınıf yerinde", () => {
  const s = renderTest(() => <DockLayoutLab />)
  for (const t of ["Dosyalar", "lab.ts", "Günlük", "Hata ayıklama", "Kilitli"]) expect(s.sees(t)).toBe(true)
  expect(s.get("#lab-dock")?.classList.contains("lab-dock")).toBe(true)
  expect(s.get(".lab-dock")?.getAttribute("aria-label")).toBe("Lab çalışma alanı")
})

test("grup düğmeleri kendi metinleriyle", () => {
  const s = renderTest(() => <DockLayoutLab />)
  expect(s.find("Tam boy")).toBeTruthy()
  expect(s.find("Şeride indir")).toBeTruthy()
  expect(s.find("Seçenekler")).toBeTruthy()
})

test("api.close onClose'a sorar; false dönünce panel kalır", async () => {
  const s = renderTest(() => <DockLayoutLab />)
  await s.click("Günlüğü kapat")
  await s.flush(4)
  expect(s.sees("kapatılan: log")).toBe(true)
  expect(s.sees("log kapandı")).toBe(true)
})

test("değişti noktası: Kaydet'e basınca kalkar", async () => {
  const s = renderTest(() => <DockLayoutLab />)
  await s.click("Kaydet")
  expect(s.find("Değiştir")).toBeTruthy()
})
